TLM.f("Tempora/Pasc7-2",{"officium":"Die III infra octavam Pentecostes","rule":["Gloria","Sequentia","Credo","Prefatio=Spiritu=hodierna die;"],"ruleInherited":["Gloria","Sequentia","Credo","Prefatio=Spiritu=hodierna die;"],"fallback":"Tempora/Pasc7-0","sections":{"Introitus":[{"k":"ref","la":"Esdr 2:36 2:37"},{"k":"text","la":"Accípite jucunditátem glóriæ vestræ, allelúja: grátias agéntes Deo, allelúja: qui vos ad cœléstia regna vocávit, allelúja, allelúja, allelúja."},{"k":"ref","la":"Ps 77:1"},{"k":"text","la":"Atténdite, pópule meus, legem meam: inclináte aurem vestram in verba oris mei."},{"k":"macro","name":"Gloria"},{"k":"text","la":"Accípite jucunditátem glóriæ vestræ, allelúja: grátias agéntes Deo, allelúja: qui vos ad cœléstia regna vocávit, allelúja, allelúja, allelúja."}],"Oratio":[{"k":"text","la":"Adsit nobis, quǽsumus, Dómine, virtus Spíritus Sancti: quæ et corda nostra cleménter expúrget, et ab ómnibus tueátur advérsis."},{"k":"macro","name":"Per Dominum eiusdem"}],"Lectio":[{"k":"text","la":"Léctio Actuum Apostolórum"},{"k":"ref","la":"Acts 8:14-17"},{"k":"text","la":"In diébus illis: Cum audíssent Apóstoli, qui erant Jerosólymis, quod recepísset Samaría verbum Dei, misérunt ad eos Petrum et Joánnem. Qui cum veníssent, oravérunt pro ipsis, ut accíperent Spíritum Sanctum: nondum enim in quemquam illórum vénerat, sed baptizáti tantum erant in nómine Dómini Jesu. Tunc imponébant manus super illos, et accipiébant Spíritum Sanctum."}],"Graduale":[{"k":"text","la":"Allelúja, allelúja."},{"k":"ref","la":"Ps 14:26"},{"k":"text","la":"Spíritus Sanctus docébit vos, quæcúmque díxero vobis. Allelúja. (Hic genuflectitur)"},{"k":"text","la":"Veni, Sancte Spíritus, reple tuórum corda fidélium: et tui amóris in eis ignem accénde.","mark":"V"}],"Sequentia":[{"k":"text","la":"Veni, Sancte Spíritus,"},{"k":"text","la":"et emítte cǽlitus"},{"k":"text","la":"lucis tuæ rádium."},{"k":"sep"},{"k":"text","la":"Veni, pater páuperum;"},{"k":"text","la":"veni, dator múnerum;"},{"k":"text","la":"veni, lumen córdium."},{"k":"sep"},{"k":"text","la":"Consolátor óptime,"},{"k":"text","la":"dulcis hospes ánimæ,"},{"k":"text","la":"dulce refrigérium."},{"k":"sep"},{"k":"text","la":"In labóre réquies,"},{"k":"text","la":"in æstu tempéries,"},{"k":"text","la":"in fletu solácium."},{"k":"sep"},{"k":"text","la":"O lux beatíssima,"},{"k":"text","la":"reple cordis íntima"},{"k":"text","la":"tuórum fidélium."},{"k":"sep"},{"k":"text","la":"Sine tuo númine"},{"k":"text","la":"nihil est in hómine,"},{"k":"text","la":"nihil est innóxium."},{"k":"sep"},{"k":"text","la":"Lava quod est sórdidum,"},{"k":"text","la":"riga quod est áridum,"},{"k":"text","la":"sana quod est sáucium."},{"k":"sep"},{"k":"text","la":"Flecte quod est rígidum,"},{"k":"text","la":"fove quod est frígidum,"},{"k":"text","la":"rege quod est dévium."},{"k":"sep"},{"k":"text","la":"Da tuis fidélibus,"},{"k":"text","la":"in te confidéntibus,"},{"k":"text","la":"sacrum septenárium."},{"k":"sep"},{"k":"text","la":"Da virtútis méritum,"},{"k":"text","la":"da salútis éxitum,"},{"k":"text","la":"da perénne gáudium."},{"k":"text","la":"Amen. Allelúja."}],"Evangelium":[{"k":"text","la":"Sequéntia ✠ sancti Evangélii secúndum Joánnem"},{"k":"ref","la":"Joannes 10:1-10"},{"k":"text","la":"In illo témpore: Dixit Jesus pharisǽis: Amen, amen, dico vobis: qui non intrat per óstium in ovíle óvium, sed ascéndit aliúnde, ille fur est et latro. Qui autem intrat per óstium, pastor est óvium. Huic ostiárius áperit, et oves vocem ejus áudiunt, et próprias oves vocat nominátim et edúcit eas. Et cum próprias oves emíserit, ante eas vadit: et oves illum sequúntur, quia sciunt vocem ejus. Aliénum autem non sequúntur, sed fúgiunt ab eo; quia non novérunt vocem alienórum. Hoc provérbium dixit eis Jesus. Illi autem non cognovérunt, quid loquerétur eis. Dixit ergo eis íterum Jesus: Amen, amen, dico vobis, quia ego sum óstium óvium. Omnes, quotquot venérunt, fures sunt et latrónes, et non audiérunt eos oves. Ego sum óstium. Per me si quis introíerit, salvábitur: et ingrediétur et egrediétur et páscua invéniet. Fur non venit, nisi ut furétur et mactet et perdat. Ego veni, ut vitam hábeant et abundántius hábeant."}],"Offertorium":[{"k":"ref","la":"Ps 77:23-25"},{"k":"text","la":"Portas cœli aperuit Dóminus: et pluit illis manna, ut éderent: panem cœli dedit eis, panem Angelórum manducávit homo, allelúja."}],"Secreta":[{"k":"text","la":"Puríficet nos, quǽsumus. Dómine, múneris præséntis oblátio: et dignos sacra participatióne effíciat."},{"k":"macro","name":"Per Dominum"}],"Communio":[{"k":"ref","la":"Joannes 15:26; 16:14"},{"k":"text","la":"Spíritus qui a Patre procédit, allelúja: ille me clarificábit, allelúja, allelúja."}],"Postcommunio":[{"k":"text","la":"Mentes nostras, quǽsumus, Dómine, Spíritus Sanctus divínis réparet sacraméntis: quia ipse est remíssio ómnium peccatórum."},{"k":"macro","name":"Per Dominum eiusdem"}]},"hr":{"e4999cda3a938c9a":{"t":"4 Ezr 2, 36 i 37, Ps 77, 1\n(4 Ezr 2, 36 i 37) Primite radost svoje slave, <i>aleluja</i>,\nzahvaljujući Bogu, <i>aleluja</i>,\nkoji vas je pozvao u nebesko kraljevstvo, <i>aleluja</i>, <i>aleluja</i>, <i>aleluja</i>.\n(Ps 77, 1) Pazi, puče moj, na zakon moj i prikloni svoje uho riječima usta mojih.\n<i>Slava Ocu, i Sinu, i Duhu Svetomu. Kako bijaše na početku, tako i sada i vazda i u vijeke vjekova. Amen</i>.\n(4 Ezr 2, 36 i 37) Primite radost svoje slave, <i>aleluja</i>,\nzahvaljujući Bogu, <i>aleluja</i>,\nkoji vas je pozvao u nebesko kraljevstvo, <i>aleluja</i>, <i>aleluja</i>, <i>aleluja</i>.\n[NAPOMENA: 4 Ezr je apokrifna knjiga koja je sastavni dio Jeronimove Vulgate (ne i Septuaginte), a preuzeta je iz starijih latinskih verzija tzv. Vetus Latina. Knjige 1 Ezr i 2 Ezr su kanonske, te se alternativno imenuju i kao Ezr i Neh (Ezra i Nehemija). Misal iz 1962 napravljen je po posttridentskoj inačici Vulgate, tzv. Klementini (po papi Klementu VIII, 1592-1605) u kojoj se 3 Ezr i 4 Ezr te druge apokrifne knjige nalaze na kraju u dodatku. U novoj verziji, tzv. Vulgata Nova (1979, 1986) apokrifne su knjige izostavljene.]","v":"iv esdr et → ∅; iv esdr et → ∅","kn":"(IV. Esdr. 2, 37). Primite radost svoje slave, aleluja, aleluja; zahvaljujući Bogu, aleluja, koji vas je pozvao u nebesko kraljevstvo, aleluja, aleluja, aleluja. (Ps. 77, 1) Pripazi, puče moj, na zakon moj i prikloni uho svoje riječima ustiju mojih. Slava Ocu . , . Primite . . .","knRef":"Kniewald 1942, str. 346–347 (snimka 174) (OCR)"},"64d04294304c39a4":{"t":"<i>Pomolimo se</i>.\nMolimo, Gospodine, da nam pomogne krepost Duha Svetoga dobrostivo čisteći naša srca i braneći nas od svih protivština.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu istog Duha Svetoga, Bog: po sve vijeke vjekova</i>.","kn":"Molimo, Gospodine, da nam pomogne krepost Duha Svetoga, čisteći blagostivo srca naša i braneći nas od svih protivština, po G, n. . . . u j edin.stvu istoga Duha ,. . .","knRef":"Kniewald 1942, str. 346–347 (snimka 174) (OCR)"},"8fe5586edcd60e3b":{"t":"Dj 8, 14-17\nČitanje Djela apostolskih. U one dane kad su čuli apostoli koji su bili u Jeruzalemu kako je Samarija primila Božju riječ, poslali su k njima Petra i Ivana. I kad su oni došli, molili su za njih da bi primili Duha Svetoga jer na njih još nije bio došao, nego su samo bili kršteni u ime Gospodina Isusa. Tada su na njih polagali ruke i primali su Duha Svetoga.","kn":"Čitanje Djela apostolskih (8, 14-17). U one dane, . kad su čuli apostoli, koji su blil u Jeruzalemu, kako je Samarija primila Božju riječ, poslali su k njima Petra i Ivana. I kad su oni došli, molili su za njih, da bi primili Duha Svetoga, jer na njih još nije bio došao, nego su samo bili kršteni u ime Gospodina Isusa. Tada su na njih polagali ruke i primali su Duha Svetoga.","knRef":"Kniewald 1942, str. 346–347 (snimka 174) (OCR)"},"ccda6b163b152602":{"t":"Io 14, 26\n<i>Aleluja</i>, <i>aleluja</i>.\nDuh će vas Sveti poučiti o svemu što vam kažem, <i>aleluja</i>.\n[Ovdje se poklekne] Dođi, Duše Sveti, napuni srca svojih vjernih i zapali u njima oganj svoje ljubavi.","kn":"Aleluja, aleluja (Iv. 14, 26). Duh će vas Sveti poučiti u svemu, što vam kažem, aileliu,ta. (Ovdje se poklekne.) Dođi Duše Sveti, napuni srca svojih vjernih i zapali u njima oganj ljubavi svoje.","knRef":"Kniewald 1942, str. 348–349 (snimka 175) (OCR)"},"8986d237bd5894a0":{"t":"Dođi, duše presveti, /Sa neba nas posjeti /Zrakom svoje milosti. <i>\n</i>\nDođi, Oče ubogih,/Djelitelju dara svih,/Dođi, srca svjetlosti. <i>\n</i>\nTješitelju tako blag, /Ti nebeski Goste drag, /Pun miline hlade tih. <i>\n</i>\nUmornima odmore,/U vrućini lahore,/Razgovore žalosnih. <i>\n</i>\nSjaju svjetla blaženog,/Sjaj u srcu puka svog,/Napuni nam dušu svu. <i>\n</i>\nBez božanstva tvojega /Svi smo mi bez ičega,/Tonemo u crnom zlu. <i>\n</i>\nNečiste nas umivaj,/Suha srca zalivaj, /Vidaj rane ranjenim. <i>\n</i>\nMekšaj ćudi kamene,/ Zagrij grudi ledene,/Ne daj nama putem zlim. <i>\n</i>\nSvim što vjeru imaju,/Što se u te ufaju, /Sedam svojih dara daj. <i>\n</i>\nDaj nam krepost zaslužnu/I smrt lijepu, blaženu,/Daj vjekovit svima raj. <i>\n</i>\n<i>amen</i>, <i>aleluja</i>."},"a1c8b39f6ab81497":{"t":"Iv 10, 1-10\nSlijedi sveto Evanđelje po Ivanu. U ono vrijeme reče Isus farizejima: Zaista, zaista vam kažem: Tko ne ulazi u ovčinjak na vrata, nego drugda, taj je tat i razbojnik. A tko ulazi na vrata, pastir je ovaca. Njemu vratar otvara i ovce slušaju njegov glas. On zove svoje ovce po imenu i izvodi ih. Kad izvede svoje ovce, ide pred njima, a ovce za njim jer poznaju njegov glas. Za tuđincem ne idu, nego od njega bježe jer ne poznaju tuđinčeva glasa. Isus im je rekao ovu prispodobu, ali oni nisu razumjeli što im je govorio. Zato im Isus reče: Zaista, zaista vam kažem: Ja sam vrata za ovce. Svi koji god su došli bili su tatovi i razbojnici i ovce ih nisu slušale. Ja sam vrata. Tko bude po meni ulazio, spasit će se: taj će ulaziti i izlaziti i nalaziti pašu. Tat ne dolazi, nego da krade i ubija i razgoni. Ja sam došao da imaju život i da ga uživaju obilno.","kn":"t Slijedi sveto evanđelje po Ivanu (10, 1-10). U ono vrijeme reče Isus farizejima: Zaista, zaista vam kažem: Tko ne ulazi u ovčinjak na vrata nego druiguda, taj je tat i razbojnik. A tko ulazi na vrata, pastir je ovaca. Njemu vratar otvara i ovce slušaju njegov glas. On zove svoje ovce po imenu i izvodi ih. Kad izvede svoje ovce, on ide pred njima, a ovce za njim, jer poznaju njegov glas, a za tuđincem ne idu, nego od njega bježe, jer ne poznaju tuđinčeva glasa. Isus im je rekao ovu prispodobu, ali oni nljesu razumjeli, što im je govorio. Zato im Isus opet reče: Zaista, zaista vam kažem: Ja sam vrata za ovce. Svi, kojigod su došli, bili su tatovi i razbojnici, i ovce ih nijesu slušale. Ja sam vrata; koji bude po meni ulazio, spasit će se: taj će ulaziti i izlaziti i nala;'ti pašu. Tat ne dolazi nego da krade i ubija i razgoni. Ja sam došao, da imaju život i da ga uživaju obilno.","knRef":"Kniewald 1942, str. 348–349 (snimka 175) (OCR)"},"2d58bb6970b71c6f":{"t":"Ps 77, 23-25\nGospodin je otvorio nebeska vrata i dao je da pada mana poput kiše da jedu. Dao im je kruh s nebesa, čovjek je blagovao anđeoski kruh, <i>aleluja</i>.","kn":"(Ps. 77, 23-25); Gospodin je otvorio .nebeska vrata i dao je da padne mana, poput kiše, da jedu; dao im je kruh s nebesa, čovjek je uživao anđeoski kruh, aleluja.","knRef":"Kniewald 1942, str. 308–309 (snimka 155) (OCR)"},"64c9c84be2709e2a":{"t":"Molimo, Gospodine, da nas prikazanje ovoga dara očisti i učini dostojnima svetog zajedništva.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>.","kn":"Molimo, Gospodine, da nas prikazanje ovoga dara očisti i učini dostojnima svetog zajedništva. po G. n.","knRef":"Kniewald 1942, str. 348–349 (snimka 175) (OCR)"},"e36be14714c3ff04":{"t":"Uistinu je dostojno i pravedno, pravo i spasonosno, da vazda i svagdje zahvaljujemo tebi, Gospodine, sveti Oče, svemogući vječni Bože, po Kristu Gospodinu našemu. On uziđe nad sva nebesa, sjede uz tvoju desnu, te obećanog Duha Svetoga na današnji dan izli na posinjenu djecu. – Stoga sav svijet na krugu zemaljskom kliče zanosnom radošću, a i višnje sile i s njima anđeoske vlasti zajedno pjevaju pjesmu tvoje slave govoreći bez prestanka:"},"d57583007f070427":{"t":"Iv 15, 26, Iv 16, 14\nDuh koji proizlazi od Oca, <i>aleluja</i>,\nproslavit će me, <i>aleluja</i>, <i>aleluja</i>.","kn":"(Iv. 15, 17). Duh, koji proizlazi od Oca, aleluja, proslavit će me, aleluja, aleluja.","knRef":"Kniewald 1942, str. 348–349 (snimka 175) (OCR)"},"989ac84c6955b78e":{"t":"<i>Pomolimo se</i>.\nMolimo, Gospodine, da Duh Sveti obnovi naše duše božanskim tajnama jer je on oproštenje grijeha.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu istog Duha Svetoga, Bog: po sve vijeke vjekova</i>.","kn":"Molimo, Gospodine, da Duh Sveti obnovi duše naše božanskim tajnama, jer on je oproštenje grijeha, po G. n. . . . u jedinstvu istoga . . .","knRef":"Kniewald 1942, str. 348–349 (snimka 175) (OCR)"}}});
